  "common.schema.json": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://schemas.nexuspipeline.invalid/1/common.schema.json",
    "$defs": {
      "uuid": {
        "type": "string",
        "format": "uuid"
      },
      "sha256": {
        "type": "string",
        "pattern": "^[0-9a-f]{64}$"
      },
      "extensionId": {
        "type": "string",
        "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$",
        "maxLength": 80
      },
      "relativePath": {
        "type": "string",
        "minLength": 1,
        "maxLength": 240,
        "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$))(?!.*[:\\\\])[A-Za-z0-9_.@/-]+$"
      },
      "utcTime": {
        "type": "string",
        "format": "date-time",
        "pattern": "Z$"
      },
      "sequence": {
        "type": "integer",
        "minimum": 1,
        "maximum": 9007199254740991
      },
      "releaseVersion": {
        "type": "string",
        "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(?:-(?:beta|rc)\\.[1-9][0-9]*)?$"
      },
      "artifactName": {
        "type": "string",
        "pattern": "^[A-Za-z][A-Za-z0-9]*$",
        "maxLength": 100
      }
    }
  },
  "configuration-selector.schema.json": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://schemas.nexuspipeline.invalid/1/configuration-selector.schema.json",
    "$defs": {
      "access": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "read",
          "write",
          "protected"
        ],
        "properties": {
          "read": {
            "type": "array",
            "maxItems": 256,
            "items": {
              "$ref": "#/$defs/grant"
            }
          },
          "write": {
            "type": "array",
            "maxItems": 256,
            "items": {
              "$ref": "#/$defs/grant"
            }
          },
          "protected": {
            "type": "array",
            "maxItems": 256,
            "items": {
              "$ref": "#/$defs/selector"
            }
          }
        }
      },
      "selector": {
        "type": "array",
        "items": {
          "$ref": "#/$defs/step"
        },
        "maxItems": 64
      },
      "step": {
        "oneOf": [
          {
            "type": "string",
            "minLength": 1,
            "maxLength": 256
          },
          {
            "type": "integer",
            "minimum": 0
          },
          {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "match"
            ],
            "properties": {
              "match": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "property",
                  "value"
                ],
                "properties": {
                  "property": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 256
                  },
                  "value": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 256
                  }
                }
              }
            }
          }
        ]
      },
      "grant": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "selector",
          "descendants"
        ],
        "properties": {
          "selector": {
            "$ref": "#/$defs/selector"
          },
          "descendants": {
            "type": "boolean"
          }
        }
      }
    }
  },
